 10→
 11→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 12→type TmuxSession struct {
 13→	name         string
 14→	stableAtSend string // stable content snapshot when Send was last called
 15→}
 16→
 17→// NewTmuxSession creates a new tmux session running the given command in dir.
 18→// unsetEnv lists environment variable names to strip from the session.
 19→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 20→	s := &TmuxSession{name: name}
 21→
 22→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 23→	// Build the shell command, prefixed with env -u for each var to strip.
 24→	shellCmd := ""
 25→	for _, v := range unsetEnv {
 26→		shellCmd += "env -u " + v + " "
 27→	}
 28→	shellCmd += command
 29→	for _, a := range args {
 30→		shellCmd += " " + a
 31→	}
 32→	tmuxArgs = append(tmuxArgs, shellCmd)
 33→
 34→	cmd := exec.Command("tmux", tmuxArgs...)
 35→	if out, err := cmd.CombinedOutput(); err != nil {
 36→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 37→	}
 38→	// Keep the pane around after the command exits so we can capture error output.
 39→	setCmd := exec.Command("tmux", "set-option", "-t", name, "remain-on-exit", "on")
 40→	_ = setCmd.Run()
 41→	return s, nil
 42→}
 43→
 44→func (s *TmuxSession) Send(input string) error {
 45→	s.stableAtSend = stableContent(s.Capture())
 46→	// Send text and Enter separately — Claude's TUI can swallow Enter
 47→	// if it arrives before the input handler finishes processing the text.
 48→	if err := s.SendKeys(input); err != nil {
 49→		return err
 50→	}
 51→	time.Sleep(200 * time.Millisecond)
 52→	return s.SendKeys("Enter")
 53→}
 54→
 55→// SendKeys sends raw tmux key names without appending Enter.
 56→func (s *TmuxSession) SendKeys(keys ...string) error {
 57→	args := append([]string{"send-keys", "-t", s.name}, keys...)
 58→	cmd := exec.Command("tmux", args...)
 59→	out, err := cmd.CombinedOutput()
 60→	if err != nil {
 61→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
 62→	}
 63→	return nil
 64→}
 65→
 66→const settleTime = 2 * time.Second
 67→
 68→// stableContent returns the content with the last few lines stripped,
 69→// so that TUI status bar updates don't prevent the settle timer.
 70→func stableContent(content string) string {
 71→	lines := strings.Split(content, "\n")
 72→	if len(lines) > 3 {
 73→		lines = lines[:len(lines)-3]
 74→	}
 75→	return strings.Join(lines, "\n")
 76→}
 77→
 78→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
 79→	re, err := regexp.Compile(pattern)
 80→	if err != nil {
 81→		return "", fmt.Errorf("invalid pattern: %w", err)
 82→	}
 83→
 84→	deadline := time.Now().Add(timeout)
 85→	var matchedAt time.Time
 86→	var lastStable string
 87→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
 88→
 89→	for time.Now().Before(deadline) {
 90→		content := s.Capture()
 91→		stable := stableContent(content)
 92→
 93→		if !re.MatchString(content) {
 94→			// Pattern lost — reset
 95→			matchedAt = time.Time{}
 96→			lastStable = ""
 97→			time.Sleep(500 * time.Millisecond)
 98→			continue
 99→		}
100→
101→		// Detect content change since Send was called
102→		if !contentChanged && stable != s.stableAtSend {
103→			contentChanged = true
104→		}
105→
106→		if stable != lastStable {
107→			// Pattern matches but content is still changing — reset settle timer
108→			matchedAt = time.Now()
109→			lastStable = stable
110→			time.Sleep(500 * time.Millisecond)
111→			continue
112→		}
113→
114→		// Pattern matches and content hasn't changed since matchedAt.
115→		// Only settle if content changed at least once after Send
116→		// (prevents false settle on echoed input before agent starts).
117→		if contentChanged && time.Since(matchedAt) >= settleTime {
118→			return content, nil
119→		}
120→
121→		time.Sleep(500 * time.Millisecond)
122→	}
123→	content := s.Capture()
124→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
125→}
126→
127→func (s *TmuxSession) Capture() string {
128→	cmd := exec.Command("tmux", "capture-pane", "-t", s.name, "-p")
129→	out, _ := cmd.Output()
130→	return strings.TrimRight(string(out), "\n")
131→}
132→
133→func (s *TmuxSession) Close() error {
134→	cmd := exec.Command("tmux", "kill-session", "-t", s.name)
135→	out, err := cmd.CombinedOutput()
136→	if err != nil {
137→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
138→	}
139→	return nil
140→}
